    12	/** The lock answered that it can't tell what the slot holds */
    13	export const SLOT_CODE_NOT_REPORTED = 'not_reported';
    14	
    15	const SLOT_CODE_SENTINELS: ReadonlySet<number | string | null> = new Set([
    16	    SLOT_CODE_EMPTY,
    17	    SLOT_CODE_UNREADABLE,
    18	    SLOT_CODE_UNANSWERED,
    19	    SLOT_CODE_DISABLED,
    20	    SLOT_CODE_CHECKING,
    21	    SLOT_CODE_NOT_REPORTED
    22	]);
    23	
    24	/** True if code is a backend label rather than a PIN */
    25	export function isSlotSentinel(code: number | string | null): boolean {
    26	    return SLOT_CODE_SENTINELS.has(code);
