                ${
                    this._actionError
                        ? html`<div class="action-error" role="alert">
                              <span>${this._actionError}</span>
                              <button
                                  class="action-error-dismiss"
                                  @click=${this._dismissActionError}
                                  aria-label="Dismiss error"
                              >
                                  ✕
                              </button>
                          </div>`
                        : nothing
                }
