    private _renderLockStatusSection(lockStatuses: LockSyncStatus[]): TemplateResult {
        const syncedCount = lockStatuses.filter((l) => l.inSync === true).length;
        const totalCount = lockStatuses.length;

        const headerExtra =
            totalCount > 0
                ? html`<span class="collapsible-badge">${syncedCount}/${totalCount}</span>`
                : undefined;

        const content =
            lockStatuses.length > 0
                ? html`<ul class="lock-list">
                      ${lockStatuses.map((lock) => html`<li>${this._renderLockRow(lock)}</li>`)}
                  </ul>`
                : html`<div class="no-conditions">No locks found</div>`;

        return this._renderCollapsible(
            'Lock Status',
            this._lockStatusExpanded,
            this._toggleLockStatus,
            content,
            headerExtra
        );
    }

    private _renderLockRow(lock: LockSyncStatus): TemplateResult {
        const showSync = this._config?.show_lock_sync !== false;

        let iconClass: string;
        let statusText: string;
        let icon: string;

        switch (lock.syncStatus) {
            case 'in_sync':
                iconClass = 'synced';
                statusText = 'Synced';
                icon = 'mdi:check-circle';
                break;
            case 'out_of_sync':
                iconClass = 'pending';
                statusText = 'Out of sync';
                icon = 'mdi:clock-outline';
                break;
            case 'syncing':
                iconClass = 'syncing';
                statusText = 'Syncing';
                icon = 'mdi:sync';
                break;
            case 'pending_confirmation':
                // An optimistic write was sent and we're waiting for the lock to
                // confirm it (push event or hard refresh). Transient; resolves to
                // synced on confirmation or re-syncs on timeout.
                iconClass = 'syncing';
                statusText = 'Confirming';
                icon = 'mdi:progress-clock';
                break;
            case 'suspended':
                iconClass = 'suspended';
                statusText = 'Suspended';
                icon = 'mdi:alert-circle';
                break;
            default:
                // Fallback for when sync_status is not available
                if (lock.inSync === true) {
                    iconClass = 'synced';
                    statusText = 'Synced';
                    icon = 'mdi:check-circle';
                } else if (lock.inSync === false) {
                    iconClass = 'pending';
                    statusText = 'Out of sync';
                    icon = 'mdi:clock-outline';
                } else {
                    iconClass = 'unknown';
                    statusText = 'Unknown';
                    icon = 'mdi:help-circle';
                }
        }

        return html`
            <div class="lock-row">
                ${
                    showSync
                        ? html`<ha-icon
                              class="lcm-sync-icon ${iconClass}"
                              icon="${icon}"
                          ></ha-icon>`
                        : nothing
                }
                <div class="lock-info">
                    <span
                        class="lock-name"
                        title="View lock codes"
                        role="button"
                        tabindex="0"
                        aria-label="View ${lock.name} more info"
                        @click=${() => this._navigateToLock(lock.lockEntityId)}
                        @keydown=${(e: KeyboardEvent) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                                e.preventDefault();
                                this._navigateToLock(lock.lockEntityId);
                            }
                        }}
                    >
                        ${lock.name}
                    </span>
                    ${
                        showSync && lock.syncStatus !== 'suspended' && lock.lastSynced
                            ? html`<span class="lock-synced-time">
                                  Last synced to lock
                                  <ha-relative-time
                                      .hass=${this._hass}
                                      .datetime=${lock.lastSynced}
                                  ></ha-relative-time>
                              </span>`
                            : showSync
                              ? html`<span class="lock-synced-time ${iconClass}"
                                    >${statusText}</span
                                >`
                              : nothing
                    }
                </div>
            </div>
        `;
    }

