    }

    /**
     * Fill the PIN field from the `generate_pin` action.
     *
     * The action owns what "safe" means -- it rejects sequences, repeats
     * and the common-leak list, and draws from `secrets` -- so this asks
     * for a PIN rather than inventing one. The result is revealed: a code
     * you cannot read is one you cannot pass on.
     */
    private async _generatePin(): Promise<void> {
        if (!this.hass || this._generating) return;
        if (
            !Number.isInteger(this._pinLength) ||
            this._pinLength < MIN_PIN_LENGTH ||
            this._pinLength > MAX_PIN_LENGTH
        ) {
            this._error = `Length must be between ${MIN_PIN_LENGTH} and ${MAX_PIN_LENGTH}`;
            return;
        }
        this._generating = true;
        this._error = undefined;
        try {
            const result = await this.hass.callService(
                'lock_code_manager',
                'generate_pin',
                { length: this._pinLength },
                undefined,
                undefined,
                true
            );
            const pin = (result?.response as { pin?: string } | undefined)?.pin;
            if (!pin) {
                throw new Error('No PIN came back');
            }
            this._pin = pin;
            this._pinVisible = true;
        } catch (err) {
            this._error = `Could not generate a PIN: ${
                err instanceof Error ? err.message : String(err)
            }`;
        } finally {
            this._generating = false;
        }
    }

    private async _commit(): Promise<void> {
        const name = this._name.trim();
        if (!name) {
            this._error = 'Give the user a name';
            return;
        }
        if (!this.hass || !this._config) {
            this._error = 'Card not initialized';
            return;
        }
        if (this._saving) return;
        this._saving = true;
        this._error = undefined;
        try {
            await this.hass.callService('lock_code_manager', 'add_user', {
                // Either/or, never both: the action treats the two as
                // exclusive and refuses a call that carries the pair.
                ...(this._config.config_entry_id
                    ? { config_entry_id: this._config.config_entry_id }
                    : { config_entry_title: this._config.config_entry_title }),
                // The list shape the action declares. The flat one still works,
                // through a shim kept for calls written before 6.0 -- but the
                // shipped card should not be the thing keeping that shim alive.
                users: [
                    {
                        enabled: this._enabled,
                        name,
                        ...(this._pin && { pin: this._pin }),
                        ...(this._condition && { condition: this._condition })
                    }
                ]
            });
        } catch (err) {
            this._error = err instanceof Error ? err.message : String(err);
            return;
        } finally {
            this._saving = false;
        }
        // The dashboard is generated by a strategy, so the new user has no
        // card until the strategy runs again. Nothing short of a reload
        // re-runs it.
        this._reload();
    }
}

