/Users/raman/.bashrc: line 2: /private/tmp/claude-501/-Users-raman/a7dfd7d7-c945-450a-b54d-0eac5add44b1/scratchpad/shell-probe.log: No such file or directory
            {
                # The field keeps its name, so a released call passing a single
                # string still validates -- it just arrives as a one-item list.
                vol.Required(CONF_NAME): vol.All(cv.ensure_list, [cv.string]),
                vol.Optional(ATTR_CLEAR_CREDENTIALS, default=True): cv.boolean,
            }
        ),
    )

    async def _generate_pin(call: ServiceCall) -> ServiceResponse:
        """Generate a random PIN that avoids known unsafe patterns."""
        return {"pin": generate_pin(call.data[ATTR_LENGTH])}

    hass.services.async_register(
        DOMAIN,
        SERVICE_GENERATE_PIN,
        _generate_pin,
        schema=vol.Schema(
            {
                vol.Optional(ATTR_LENGTH, default=DEFAULT_PIN_LENGTH): vol.All(
                    vol.Coerce(int), vol.Range(min=MIN_PIN_LENGTH, max=MAX_PIN_LENGTH)
                ),
            }
        ),
        supports_response=SupportsResponse.ONLY,
    )

    async def _deobfuscate_log(call: ServiceCall) -> ServiceResponse:
        """Reverse mask_pin() tokens in pasted log text against the current config."""
        instance_id = hass.data.get(DATA, LockCodeManagerData()).get("instance_id", "")
        if not instance_id:
      selector:
        text:
          multiple: true
    clear_credentials:
      default: true
      selector:
        boolean:

generate_pin:
  fields:
    length:
      default: 4
      example: 4
      selector:
        number:
          min: 4
          max: 12
          step: 1
          mode: box

deobfuscate_log:
  fields:
    text:
      required: true
      selector:
        text:
        "name": {
          "name": "Name",
          "description": "The person. Matched ignoring case and surrounding whitespace, so it need not be spelled exactly as stored."
        }
      }
    },
    "generate_pin": {
      "description": "Generate a random PIN that avoids known unsafe patterns (all-same digits, sequential digits, repeating sub-sequences, and common weak PINs). Returns the PIN via response_variable.",
      "name": "Generate PIN",
      "fields": {
        "length": {
          "description": "Number of digits in the generated PIN (4-12). Defaults to 4.",
          "name": "Length"
        }
      }
    },
    "hard_refresh_usercodes": {
      "description": "If Lock Code Manager supports the lock's integration, and the lock's integration supports it, this will query the lock for all usercodes. This is potentially useful for integrations that cache data from the lock and a usercode(s) is configured outside of Home Assistant.",
      "name": "Hard refresh usercodes",
      "fields": {
        "forget_reporting": {
}

export interface HomeAssistant {
    config: HassConfig;
    connection: Connection;
    resources: object;
    states: HassEntities;
    // Home Assistant's own signature, which carries more than the void this
    // used to claim: a service declaring a response hands it back here, and
    // `generate_pin` is one.
    // eslint-disable-next-line typescript-sort-keys/interface -- Methods grouped logically, not alphabetically
    callService(
        domain: string,
        service: string,
        data?: object,
        target?: object,
        notifyOnError?: boolean,
        returnResponse?: boolean
    ): Promise<ServiceCallResponse>;
    callWS<T>(msg: MessageBase): Promise<T>; // eslint-disable-line typescript-sort-keys/interface -- Methods grouped logically, not alphabetically
}
- **Import/export slot configuration**
- **PIN validation** — Warn on simple PINs ("1234", "0000"), duplicate PINs
  across slots, format violations against lock requirements, and slot conflicts
  across config entries.
- **Service actions:**
  - `generate_pin` — auto-generate secure PIN
- **Custom Jinja templates** — Ship `.jinja` macros for LCM entity resolution
  (e.g. `lcm_slot_entities(config_entry_id, slot_num)`). Auto-install to
  `custom_templates/` during setup.

